import json,csv,html
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def main():
    out=ROOT/'output';s=json.loads((out/'optimization_summary.json').read_text(encoding='utf-8'));g=json.loads((out/'route_geometry_summary.json').read_text(encoding='utf-8'))
    with (out/'route_geometry_comparison.csv').open(encoding='utf-8-sig') as f:rs=[r for r in csv.DictReader(f) if r.get('review')=='requires_turn_and_bus_feasibility_review']
    unique={}
    for r in rs:
        key=(r['from_node'],r['to_node']);unique.setdefault(key,{'row':r,'routes':[]})['routes'].append(r['route'])
    with (out/'transfer_before_after.csv').open(encoding='utf-8-sig') as f:transfers=list(csv.DictReader(f))
    examples=[r for r in transfers if r['saved_min'] and 5<=float(r['saved_min'])<=20][:3]
    worse=[r for r in transfers if r['saved_min'] and -15<=float(r['saved_min'])<=-5][:2]
    reduction=(1-s['after']['mean_wait']/s['before']['mean_wait'])*100
    source='https://xn--h1aecgfmj1g.xn--p1ai/ser/files/itogi_9mes_2025.pdf'
    (ROOT/'data/passenger_flow_sources.json').write_text(json.dumps({'sources':[{'url':source,'title':'Итоги социально-экономического развития Норильска за 9 месяцев 2025 года','page':75,'period':'2025-01 through 2025-09','municipal_bus_passengers':8778800,'all_bus_passengers':9033000,'granularity':'municipality totals only','used_as_od_weights':False}],'route_stop_od_counts_found':False},ensure_ascii=False,indent=2),encoding='utf-8')
    def esc(x):return html.escape(str(x))
    def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
    page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Норильск — результаты оптимизации</title><style>body{margin:0;background:#f0f4f8;color:#17324c;font:17px/1.55 system-ui}main{max-width:1120px;margin:40px auto;padding:0 24px}h1{font-size:38px;line-height:1.2}h2{font-size:26px}section{background:white;border-radius:16px;padding:28px;margin:24px 0;box-shadow:0 4px 20px #19304b09}.cards{display:flex;gap:16px;flex-wrap:wrap}.card{flex:1;background:#edf5fa;padding:18px;border-radius:10px;min-width:180px}.big{font-size:32px;font-weight:700}.muted{color:#526a7e}table{width:100%;border-collapse:collapse;font-size:15px}td,th{padding:12px;text-align:left;border-bottom:1px solid #e1e7ee}th{color:#526a7e}.bar{height:24px;background:#1769aa;border-radius:5px;margin:8px 0}.note{border-left:4px solid #d69529;padding:12px 18px;background:#fff9ec}a{color:#056bad}details{margin:14px 0}button{padding:10px 18px;border:0;background:#1769aa;color:white;border-radius:7px;cursor:pointer}@media print{body{background:white}section{box-shadow:none;break-inside:avoid}button{display:none}}</style><main><p class="muted">Исследование транспортной доступности • Центральный район Норильска</p><h1>Что можно изменить в расписании и трассах автобусов</h1><p>Два самостоятельных расчёта на предоставленных расписаниях и картографических данных. Для каждого показаны результат и условия его применимости.</p><button onclick="window.print()">Печать / сохранить PDF</button>'''
    page+=f'<section><h2>1. Согласовать пересадки на АДЦ</h2><p>Проверенное предложение: перенести все импортированные рейсы маршрута <b>№{s["selected_route"]} на {s["shift_min"]} минут позже</b>. Рейсы не отменяются; интервалы и длительность движения сохраняются.</p><div class="cards"><div class="card">Среднее ожидание в модели<div class="big">{s["before"]["mean_wait"]:.2f} → {s["after"]["mean_wait"]:.2f}</div>минуты</div><div class="card">Снижение среднего<div class="big">{reduction:.1f}%</div>для проверенных возможностей пересадки</div><div class="card">Проверено вариантов<div class="big">{s["candidates"]}</div>сдвиги одного маршрута от −10 до +10 минут</div></div>'
    page+=f'<p>Улучшилось: <b>{s["improved"]}</b> возможностей пересадки. Ухудшилось: <b>{s["worsened"]}</b>. Без изменений: <b>{s["unchanged"]}</b>. Это не количество пассажиров.</p>'
    page+='<h3>Как это выглядит для поездки</h3>'+table(['Прибытие на АДЦ','Пересадка','Ожидание было','Стало','Изменение'],[[f'№{r["incoming_route"]}, {r["arrival_before"]}',f'№{r["outgoing_route"]} → {r["outgoing_destination"]}',f'{float(r["wait_before_min"]):.1f} мин',f'{float(r["wait_after_min"]):.1f} мин',f'{float(r["saved_min"]):+.1f} мин экономии'] for r in examples+worse])
    page+='<p class="note">Почему среднее ожидание большое? Проверяется пересадка на каждое выбранное направление, даже если следующий рейс будет после длительного перерыва. Это не средняя длительность реальных поездок жителей и не прогноз пассажирской экономии.</p><details><summary>Условия расчёта</summary><p>Будни, прибытия с 07:00 до 10:00, переход между платформами 5 минут. Исходящие направления имеют минимум три отправления в этом окне. Вес каждой возможности равен 1. Проверены также переходы 2, 3 и 8 минут; для выбранного сдвига среднее ожидание тоже уменьшилось. Согласование с другими узлами, сменами водителей и оборотом автобусов ещё требуется.</p></details><p><a href="optimization_report.html">Полный расчёт времени</a> · <a href="schedule_proposal.csv">Предлагаемые времена</a> · <a href="transfer_before_after.csv">Все улучшения и ухудшения</a></p></section>'
    page+='<section><h2>2. Проверить более короткие участки существующих маршрутов</h2><p>Вместо нового маршрута на окраине проверены пути между последовательными остановками. Сохраняются обе остановки и порядок обслуживания. Сокращение измерено в метрах, без выдуманной скорости.</p>'
    page+=table(['Маршруты','Участок','По OSM было','Кандидат','Сокращение'],[[', '.join(x['routes']),x['row']['from_name']+' → '+x['row']['to_name'],x['row']['before_m']+' м',x['row']['after_m']+' м',x['row']['saved_m']+' м'] for x in unique.values()])
    page+=f'<p>Проверено {g["tested_directed_segments"]} участков направлений. Найдено {len(unique)} различных пар остановок с выигрышем больше 50 м; некоторые обслуживаются несколькими маршрутами. {g["unresolved_segments"]} участков не восстановлены и не участвовали в сравнении.</p><p class="note">Это кандидаты для проверки, не утверждённые изменения трасс. Исходная линия восстановлена по OSM, а не GPS. Проверены направления улиц и основные ограничения доступа; запреты конкретных поворотов, габариты и возможность проезда автобуса требуют отдельной проверки. Экономия времени и топлива здесь не заявляется.</p><p><a href="route_geometry_report.html">Схема и расчёты участков</a> · <a href="route_variants.geojson">Геометрия вариантов</a></p></section>'
    page+=f'<section><h2>Что найдено о пассажиропотоке</h2><p>В официальном отчёте за 9 месяцев 2025 года указано <b>9 033,0 тыс. перевезённых пассажиров</b>, в том числе <b>8 778,8 тыс.</b> у МУП «Норильский транспорт». Это агрегат по муниципальному образованию, а не по центральному району или остановкам.</p><p><a href="{source}">Источник: отчёт администрации, страница 75</a>.</p><p>Открытую таблицу посадок/высадок по остановкам и времени получить не удалось. Поэтому найденные общие числа не используются как веса поездок. Для следующего шага нужны обезличенные посадки и высадки по рейсу, остановке и часу, отдельно для будней и выходных; желательно также заполнение салона на перегонах.</p></section><section><h2>Как воспроизвести</h2><p>Запустить <b>main.py</b> в PyCharm. Он пересчитает расписание, варианты участков и эту страницу. Параметры времени находятся в optimization_config.json. Исходные таблицы не меняются.</p><p class="muted">Материалы для научной работы: постановка критерия, полный перечень кандидатов, сравнение до/после, проверка чувствительности и ограничения данных. Результаты представлены отдельно для расписания и геометрии: их эффекты не складываются.</p></section></main></html>'
    (out/'results.html').write_text(page,encoding='utf-8');print(out/'results.html')
if __name__=='__main__':main()
